      "majority_option": "sum_i x[i,j] >= demand[j]"
    },
    {
      "decision": "capacity_link_form",
      "evidence": "\"Each distribution center has its own fixed opening cost and a maximum supply capacity\"",
      "options": [
        "sum_j x[i,j] <= capacity[i] * y[i]",
        "sum_j x[i,j] <= capacity[i] and x[i,j] <= capacity[i]*y[i] per store"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "sum_j x[i,j] <= capacity[i] * y[i]"
    },
    {
      "decision": "objective_components",
      "evidence": "\"minimizing the total operational cost, which includes both the opening of distribution centers and the transportation of goods\"",
      "options": [
        "minimize sum_i opening_cost[i]*y[i] + sum_ij trans_cost[i,j]*x[i,j]",
        "minimize sum_ij trans_cost[i,j]*x[i,j] only"
      ],
      "plausibility": [
        0.97,
        0.03
      ],
      "majority_option": "minimize sum_i opening_cost[i]*y[i] + sum_ij trans_cost[i,j]*x[i,j]"
    },
    {
      "decision": "opening_variable_domain",
      "evidence": "\"six possible distribution centers to choose from\"",
      "options": [
        "Binary",
        "NonNegativeReals in [0,1]"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "Binary"
    },
    {
      "decision": "cost_units_scale",
      "evidence": "\"Opening Costs ... (in dollars)\" and \"Transportation Cost Per Unit ... (in dollars)\"",
      "options": [
        "report total cost in dollars",
        "report total cost in thousands of dollars"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "report total cost in dollars"
    }
  ]
